-- Kinder im Werk editorial JSON conversion
-- Generated: 2026-06-23
-- Applies the curated _iss_editorial_ausstellung document and enables JSON rendering for post 26381.

DELETE FROM wp_postmeta WHERE post_id = 26381 AND meta_key IN ('_iss_editorial_ausstellung', '_iss_editorial_enabled_ausstellung', '_iss_editorial_ausstellung_autosave');

INSERT INTO wp_postmeta (post_id, meta_key, meta_value) VALUES
(26381, '_iss_editorial_ausstellung', '{\"schema_version\":1,\"skin\":\"kinder-im-werk\",\"variant\":\"standard\",\"sections\":[{\"type\":\"zitat\",\"kicker\":\"Auftakt\",\"title\":\"Jetzt geht es uns gut.\",\"body\":\"\",\"quote\":\"Jetzt geht es uns gut.\",\"attribution\":\"Bildunterschrift zur Kinderkrippe des HF, Betriebszeitung HF-Sender, Nr. 16, 28. Mai 1954.\",\"object_refs\":[]},{\"type\":\"leitfrage\",\"kicker\":\"Leitfrage\",\"title\":\"Wer betreut die Kinder, wenn die Mütter im Werk arbeiten?\",\"body\":\"Die Quellen erzählen von Fürsorge und Entlastung. Gleichzeitig zeigen sie, dass Kinderbetreuung auch eine Bedingung der Produktion war: Frauen sollten arbeiten können, Schichten sollten laufen, eingearbeitete Kräfte sollten im Betrieb bleiben.\"},{\"type\":\"quellenauszug\",\"kicker\":\"1 · Kinderkrippe\",\"title\":\"Betreuung als Produktionsfrage\",\"body\":\"Die frühe Berichterstattung zeigt die Kinderkrippe als liebevollen Ort. Doch der Text sagt auch offen, weshalb der Betrieb sie brauchte: Die Mütter sollten sich voll und ganz für die Erfüllung der Produktionspläne einsetzen können.\",\"quote\":\"Die Muttis wissen, wieviel liebevolle Geduld und rastlose Arbeit die Pflege eines Kleinkindes erfordert …\",\"attribution\":\"HF-Sender, 1954\",\"object_refs\":[],\"media_refs\":[{\"kind\":\"media\",\"source\":\"wp-media\",\"id\":\"13824\",\"label\":\"HF-Sender Nr. 16, Titelseite zur Kinderkrippe, 1954.\",\"thumbnail\":\"http://192.168.2.31:8082/wp-content/uploads/2023/12/HF-Sender-16-Titelseite-300x276.jpg\",\"width\":\"441\",\"height\":\"405\"}],\"orientation\":\"media-left\"},{\"type\":\"objektfokus\",\"kicker\":\"Objektfokus\",\"title\":\"Drei Quellen, drei Blickrichtungen\",\"body\":\"Die Ausstellung bindet Archivobjekte direkt ein. Nicht als Kartengitter am Ende, sondern als kleine Beweisstücke mitten in der Erzählung.\",\"object_refs\":[{\"kind\":\"archive_object\",\"source\":\"iss-archive\",\"id\":\"26215\",\"label\":\"HF-Sender Nr. 16: Titelseite zur Kinderkrippe\",\"thumbnail\":\"http://192.168.2.31:8082/wp-content/uploads/2023/12/HF-Sender-16-Titelseite-300x276.jpg\",\"set_id\":\"13\",\"set_title\":\"Kinder im WF - Bildauswahl\"},{\"kind\":\"archive_object\",\"source\":\"iss-archive\",\"id\":\"26217\",\"label\":\"Kinder mit Erzieherin am Sandkasten vor dem WF-Gebäude\",\"thumbnail\":\"http://192.168.2.31:8082/wp-content/uploads/2024/01/kinder-mit-erzieherin-spielen-im-sandkasten-auf-dem-spielplatz-vor-dem-gebaeude-des-wf-kin-300x284.jpg\",\"set_id\":\"13\",\"set_title\":\"Kinder im WF - Bildauswahl\"},{\"kind\":\"archive_object\",\"source\":\"iss-archive\",\"id\":\"26219\",\"label\":\"BVV-Unterlage zur Kinderbetreuung, 1973\",\"thumbnail\":\"http://192.168.2.31:8082/wp-content/uploads/2024/02/BVV-1973-236x300.jpg\",\"set_id\":\"13\",\"set_title\":\"Kinder im WF - Bildauswahl\"}]},{\"type\":\"quellenauszug\",\"kicker\":\"2 · Kinderwochenheim\",\"title\":\"Montagmorgen gebracht. Freitagnachmittag abgeholt.\",\"body\":\"Das Kinderheim Agnes Smedley war zeitweise ein Kinderwochenheim. Neben Tagesgruppen gab es Heimgruppen, in denen Kinder die Woche über blieben. Für heutige Besucher ist das erklärungsbedürftig — und genau deshalb ausstellungsstark.\",\"quote\":\"\",\"attribution\":\"\",\"object_refs\":[],\"media_refs\":[{\"kind\":\"media\",\"source\":\"wp-media\",\"id\":\"23627\",\"label\":\"Kinderheim Julius Rosenberg, Gartenfront; Foto 1962\",\"thumbnail\":\"http://192.168.2.31:8082/wp-content/uploads/2026/05/kinderheim-julius-rosenberg-gartenfront-foto-1962-65505-300x229.jpg\",\"width\":\"1000\",\"height\":\"763\"}],\"orientation\":\"media-right\"},{\"type\":\"bildstrecke\",\"kicker\":\"Dokumentarische Strecke\",\"title\":\"Schlafen. Spielen. Hausaufgaben.\",\"body\":\"Eine Ausstellung muss hier nicht alles erklären. Drei bis vier Bilder können zeigen, dass Betreuung aus Routinen bestand: Essen, Schlafen, Lernen, Abholen, Wäsche, Wochenrhythmus.\",\"object_refs\":[],\"media_refs\":[{\"kind\":\"media\",\"source\":\"wp-media\",\"id\":\"20899\",\"label\":\"Schlafräume im Kinderheim.\",\"thumbnail\":\"http://192.168.2.31:8082/wp-content/uploads/2026/05/TFA-6221489-1-300x224.jpg\",\"width\":\"400\",\"height\":\"298\"},{\"kind\":\"media\",\"source\":\"wp-media\",\"id\":\"20100\",\"label\":\"Gruppenalltag im Kinderheim.\",\"thumbnail\":\"http://192.168.2.31:8082/wp-content/uploads/2026/05/drei-kinder-und-erzieherin-im-kinderheim-foto-juli-1954-64518-1-300x206.jpg\",\"width\":\"1000\",\"height\":\"687\"},{\"kind\":\"media\",\"source\":\"wp-media\",\"id\":\"13812\",\"label\":\"Kinder im Planschbecken, Foto 1977.\",\"thumbnail\":\"http://192.168.2.31:8082/wp-content/uploads/2024/01/kinder-im-planschbecken-juni-1977-sw-foto-kurt-schwarz-95017-300x200.jpg\",\"width\":\"960\",\"height\":\"640\"},{\"kind\":\"media\",\"source\":\"wp-media\",\"id\":\"20102\",\"label\":\"Szene im Kindergarten des Werkes, 1954.\",\"thumbnail\":\"http://192.168.2.31:8082/wp-content/uploads/2026/05/TFA-549681-1-300x205.jpg\",\"width\":\"400\",\"height\":\"273\"}]},{\"type\":\"quellenauszug\",\"kicker\":\"3 · Neue Mühle\",\"title\":\"Ein Ort außerhalb der Werkhalle\",\"body\":\"Mit Neue Mühle verschiebt sich die Geschichte. Es geht nicht mehr nur um Betreuung während der Arbeitszeit, sondern um eine eigene Kinderwelt: Haus, Gelände, Erholung, Ferien und Ausflüge.\",\"quote\":\"Dieses Kapitel sollte eher bildhaft als argumentativ sein. Ein großes Foto, kurze Sätze, wenige Daten.\",\"attribution\":\"Ausstellungsentscheidung\",\"object_refs\":[],\"media_refs\":[{\"kind\":\"media\",\"source\":\"wp-media\",\"id\":\"13809\",\"label\":\"Kinder mit Erzieherin am Sandkasten vor dem WF-Gebäude.\",\"thumbnail\":\"http://192.168.2.31:8082/wp-content/uploads/2024/01/kinder-mit-erzieherin-spielen-im-sandkasten-auf-dem-spielplatz-vor-dem-gebaeude-des-wf-kin-300x284.jpg\",\"width\":\"960\",\"height\":\"909\"}],\"orientation\":\"media-left\"},{\"type\":\"massstab\",\"kicker\":\"4 · Maßstab\",\"title\":\"Kinderbetreuung war kein Randthema.\",\"body\":\"<strong>8.615</strong> Beschäftigte im WF im Jahr 1990\\n\\n<strong>3.503</strong> davon Frauen\\n\\n<strong>1.754</strong> Frauen mit Kindern\\n\\nDie Zahlen holen die Ausstellung zurück in den Betrieb. Kinderbetreuung betraf den Alltag vieler Familien und die Arbeitsfähigkeit eines großen Industriebetriebs.\"},{\"type\":\"fliesstext\",\"kicker\":\"5 · Für wen?\",\"title\":\"Wochenheime waren nicht für alle gleich.\",\"body\":\"Die Quellen mahnen zur Vorsicht vor schnellen Urteilen. Wochenkrippen und Kinderwochenheime wirkten damals nicht nur als staatliche Zumutung, sondern auch als Lösung für Alleinerziehende, Studierende, Schichtarbeitende und Familien ohne andere Betreuung.\\n\\nGerade deshalb sollte die Ausstellung die Spannung halten: Entlastung und Zumutung, Fürsorge und Produktionsinteresse, Schutzraum und Trennung.\\n\\nQuellenhintergrund: Folge 8 der Serie behandelt die Frage, für wen Wochenkrippen und Kinderwochenheime gedacht waren.\"},{\"type\":\"quellenauszug\",\"kicker\":\"6 · Ambivalenz\",\"title\":\"Fürsorge genügt nicht, wenn Bindung fehlt.\",\"body\":\"Spätere Untersuchungen diskutierten mögliche Folgen von Wochenkrippen und Wochenheimen. Die Ausstellung muss diesen Teil nicht dramatisieren, aber sie sollte ihn nicht aussparen.\",\"quote\":\"\",\"attribution\":\"\",\"object_refs\":[],\"media_refs\":[{\"kind\":\"media\",\"source\":\"wp-media\",\"id\":\"20899\",\"label\":\"Kinderheim Julius Rosenberg, Kinderschlafsaal; Foto 1962\",\"thumbnail\":\"http://192.168.2.31:8082/wp-content/uploads/2026/05/TFA-6221489-1-300x224.jpg\",\"width\":\"400\",\"height\":\"298\"}],\"orientation\":\"media-right\"},{\"type\":\"schluss\",\"kicker\":\"Schluss\",\"title\":\"Die Kinderbetreuung im WF war mehr als Sozialleistung.\",\"body\":\"Sie führte vom Werkstor in Krippenräume, Wochenheime und Ferienorte. Sie half Müttern, im Betrieb zu bleiben. Sie griff tief in den Familienalltag ein. Die Quellen zeigen eine Geschichte von Fürsorge, Arbeit, Organisation und Widerspruch.\",\"links\":[{\"label\":\"Archivbestand\",\"url\":\"/archiv/?s=Kinder\"},{\"label\":\"Kinder im WF\",\"url\":\"/ausstellungen/kinder-im-wf/\"},{\"label\":\"Weitere Ausstellungen\",\"url\":\"/ausstellungen/\"}]}]}'),
(26381, '_iss_editorial_enabled_ausstellung', '1');
